pub const DYNAMIC_COUNT: usize = 136;

#[derive(Debug, Clone)]
pub struct ModelIndices {
    ids: [i16; DYNAMIC_COUNT],
}

impl Default for ModelIndices {
    fn default() -> Self {
        Self { ids: [-1; DYNAMIC_COUNT] }
    }
}

impl ModelIndices {
    /// `InitModelIndices`: forget all matches.
    pub fn reset(&mut self) {
        self.ids = [-1; DYNAMIC_COUNT];
    }

    /// `MatchModelString`: record `id` if `name` is one of the tracked models (exact match).
    pub fn match_model_string(&mut self, name: &str, id: i16) -> bool {
        match DYNAMIC_NAMES.iter().position(|(n, _)| *n == name) {
            Some(i) => {
                self.ids[i] = id;
                true
            }
            None => false,
        }
    }

    /// Id matched for slot `s` (see [`slot`]), or -1.
    pub fn get(&self, s: usize) -> i16 {
        self.ids[s]
    }

    pub fn is_traffic_light(&self, id: i16) -> bool {
        id == self.get(slot::TRAFFICLIGHTS) || id == self.get(slot::TRAFFICLIGHTS_VERTICAL) || id == self.get(slot::TRAFFICLIGHTS_MIAMI) || id == self.get(slot::TRAFFICLIGHTS_TWOVERTICAL)
    }

    pub fn is_light_without_shift(&self, id: i16) -> bool {
        id == self.get(slot::TRAFFICLIGHTS) || id == self.get(slot::SINGLESTREETLIGHTS1) || id == self.get(slot::SINGLESTREETLIGHTS2) || id == self.get(slot::SINGLESTREETLIGHTS3) || id == self.get(slot::DOUBLESTREETLIGHTS)
    }

    pub fn is_light_with_pre_render_effects(&self, id: i16) -> bool {
        self.is_traffic_light(id) || id == self.get(slot::SINGLESTREETLIGHTS1) || id == self.get(slot::SINGLESTREETLIGHTS2) || id == self.get(slot::SINGLESTREETLIGHTS3) || id == self.get(slot::DOUBLESTREETLIGHTS)
    }

    pub fn is_light_that_needs_repositioning(&self, id: i16) -> bool {
        id == self.get(slot::SINGLESTREETLIGHTS1) || id == self.get(slot::SINGLESTREETLIGHTS2) || id == self.get(slot::SINGLESTREETLIGHTS3) || id == self.get(slot::TRAFFICLIGHTS_MIAMI) || id == self.get(slot::TRAFFICLIGHTS_TWOVERTICAL) || id == self.get(slot::MLAMPPOST) || id == self.get(slot::STREETLAMP1) || id == self.get(slot::STREETLAMP2)
    }

    pub fn is_light_object(&self, id: i16) -> bool {
        id == self.get(slot::TRAFFICLIGHTS_MIAMI) || id == self.get(slot::MLAMPPOST) || id == self.get(slot::SINGLESTREETLIGHTS1) || id == self.get(slot::SINGLESTREETLIGHTS2) || id == self.get(slot::SINGLESTREETLIGHTS3) || id == self.get(slot::DOUBLESTREETLIGHTS) || id == self.get(slot::TRAFFICLIGHTS_TWOVERTICAL)
    }

    pub fn is_lamp_post(&self, id: i16) -> bool {
        id == self.get(slot::SINGLESTREETLIGHTS1) || id == self.get(slot::SINGLESTREETLIGHTS2) || id == self.get(slot::SINGLESTREETLIGHTS3) || id == self.get(slot::BOLLARDLIGHT) || id == self.get(slot::MLAMPPOST) || id == self.get(slot::STREETLAMP1) || id == self.get(slot::STREETLAMP2) || id == self.get(slot::TELPOLE02) || id == self.get(slot::TRAFFICLIGHTS_MIAMI) || id == self.get(slot::TRAFFICLIGHTS_TWOVERTICAL)
    }

    pub fn is_body_part(&self, id: i16) -> bool {
        id == mi::BODYPARTA || id == mi::BODYPARTB
    }

    pub fn is_ped_model(&self, id: i16) -> bool {
        id >= mi::PLAYER && id <= mi::LAST_PED
    }

    pub fn is_palm_tree_model(&self, id: i16) -> bool {
        id == self.get(slot::VEG_PALM01) || id == self.get(slot::VEG_PALM02) || id == self.get(slot::VEG_PALM03) || id == self.get(slot::VEG_PALM04) || id == self.get(slot::VEG_PALM05) || id == self.get(slot::VEG_PALM06) || id == self.get(slot::VEG_PALM07) || id == self.get(slot::VEG_PALM08)
    }

    pub fn is_tree_model(&self, id: i16) -> bool {
        id == self.get(slot::TREE2) || id == self.get(slot::TREE3) || id == self.get(slot::TREE6) || id == self.get(slot::TREE8) || self.is_palm_tree_model(id)
    }

    pub fn is_police_ped_model(&self, id: i16) -> bool {
        id == mi::COP || id == mi::SWAT || id == mi::FBI || id == mi::ARMY
    }

    pub fn is_police_vehicle_model(&self, id: i16) -> bool {
        id == mi::CHOPPER || id == mi::PREDATOR || id == mi::POLICE || id == mi::ENFORCER
    }

    pub fn is_explosive_thing_model(&self, id: i16) -> bool {
        id == self.get(slot::EXPLODINGBARREL) || id == self.get(slot::PETROLPUMP) || id == self.get(slot::PETROLPUMP2)
    }

    pub fn is_fence(&self, id: i16) -> bool {
        id == self.get(slot::FENCE) || id == self.get(slot::FENCE2)
    }

}
